import {intro} from './intro.mjs';
const $=id=>document.getElementById(id);
const views={home:['ENDEAVOR 소개','스마트 슈즈 기반 보행 모니터링 프로젝트'],dashboard:['홈 대시보드','일상의 걸음과 건강 기록을 한눈에 확인하세요.'],measurement:['실시간 측정','두 ESP32를 각각 연결하고 발별 보정 후 보행을 기록하세요.'],analysis:['보행 분석','개인 기준선과 비교한 변화 정도를 확인하세요.'],trends:['장기 추이','같은 조건·보정의 기록을 골라 시간에 따른 변화를 살펴보세요.'],reports:['건강 리포트','저장된 보행·복약 기록으로 기간별 리포트를 만드세요.'],medications:['복약 관리','처방받은 내용을 직접 등록하고 복약 여부를 기록하세요.'],chat:['AI 건강상담','궁금한 점을 기록하고 측정·복약 관리에 관한 기본 안내를 확인하세요.'],sharing:['보호자·의료진 공유','함께 확인할 사람을 등록하고 전달할 리포트 파일을 준비하세요.'],care:['방문 케어 연계','방문 케어 상담에 필요한 요청서를 작성하고 보관하세요.']};
const icons=['M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 8v5m0-8h.01','M3 10 12 3l9 7v10H3Z M9 20v-7h6v7','M3 12h4l3-7 4 14 3-7h4','M5 20V9m7 11V4m7 16v-7','M3 18l6-7 5 3 7-10','M5 3h10l4 4v14H5Z M9 11h6m-6 4h6','M6 6a5 5 0 0 1 7 0l5 5a5 5 0 0 1-7 7l-5-5a5 5 0 0 1 0-7Zm2 2 8 8','M4 4h16v12H9l-5 4Z M8 9h8m-8 3h5','M9 8l6-3m-6 9 6 4 M9 11a3 3 0 1 1-6 0 3 3 0 0 1 6 0Zm12-8a3 3 0 1 1-6 0 3 3 0 0 1 6 0Zm0 17a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z','M3 11l9-8 9 8v10H3Z M9 13h6m-3-3v6'];
const metricNames={pitch_range:'피치 범위',forefoot_peak:'전족부 피크',heel_peak:'뒤꿈치 피크',pressure_ratio:'전족부/뒤꿈치 비',forefoot_contact:'전족부 접촉시간',heel_contact:'뒤꿈치 접촉시간',total_contact:'전체 접촉시간',interval_mean:'접촉 시작 간격',interval_sd:'간격 SD',interval_cv:'간격 CV'};
const metricUnit=key=>key==='pitch_range'?'°':key==='interval_cv'?'%':key.includes('contact')||key.startsWith('interval_')?'s':key==='pressure_ratio'?'비':'상대값';
let participant='P1',data,coreState={trials:[],devices:{}},requestVersion=0,currentView='home',printing=null;
const esc=value=>String(value??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const number=(n,d=1)=>Number.isFinite(n)?n.toFixed(d):'—';
const dayNow=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateOf=value=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const stamp=value=>new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'});
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function message(text,error=false){$('platform-notice').hidden=!text;$('platform-notice').textContent=text;$('platform-notice').classList.toggle('error',error);}
async function api(path,payload){const r=await fetch(path,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const value=await r.json();if(!r.ok)throw Error(value.error||'저장에 실패했습니다.');return value;}
async function load(){const version=++requestVersion,who=participant;try{const value=await api('/api/platform?participant='+encodeURIComponent(who));if(version!==requestVersion)return;data=value;render();}catch(e){if(version===requestVersion)message(e.message,true);}}
async function action(name,payload){if(!data||data.participant_id!==participant)throw Error('참여자 기록을 불러온 뒤 다시 시도하세요.');const who=participant;const result=await api('/api/platform/'+name,{...payload,participant_id:who});if(participant===who)await load();return result;}
function navigate(view){if(!views[view])view='home';const changed=currentView!==view;currentView=view;document.body.dataset.view=view;document.title=view==='home'?'ENDEAVOR · 스마트 슈즈 보행 모니터링':'ENDEAVOR · 보행 연구 대시보드';for(const panel of document.querySelectorAll('[data-view-panel]'))panel.hidden=panel.dataset.viewPanel!==view;for(const button of document.querySelectorAll('[data-nav]')){if(button.dataset.nav===view)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}$('view-title').textContent=views[view][0];$('view-subtitle').textContent=views[view][1];$('view-eyebrow').textContent='ENDEAVOR / '+String(Object.keys(views).indexOf(view)+1).padStart(2,'0');document.body.classList.remove('menu-open');$('menu-toggle').setAttribute('aria-expanded','false');history.replaceState(null,'','#'+view);syncMenu();if(changed)window.scrollTo(0,0);}
window.earlybirdNavigate=navigate;

const sidebar=`<div class="sidebar-brand"><div><strong>ENDEAVOR</strong><span>걸음으로 이어지는 일상</span></div></div><p class="nav-label">나의 건강 공간</p><nav>${Object.entries(views).map(([key,value],i)=>`<button data-nav="${key}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[i]}"/></svg><span>${value[0]}</span></button>`).join('')}</nav><div class="sidebar-bottom"><span class="local-dot"></span> 이 PC에 안전하게 기록<p>보행 연구 · 로컬 서비스<br>MPU6500 · FSR406 ×2 / 발</p><a href="guide.html" target="_blank" rel="noopener">시작 가이드 보기 ↗</a></div>`;
const home=`<section data-view-panel="dashboard"><div class="home-hero"><div><p class="eyebrow">EVERY STEP, A RECORD</p><h2>매일의 걸음,<br>하나의 기록으로.</h2><p>보행의 변화부터 복약과 돌봄 준비까지.<br>오늘의 기록을 차근차근 이어가세요.</p><div class="actions"><button data-go="measurement">실시간 측정 시작 <span aria-hidden="true">→</span></button><button data-go="reports" class="secondary">리포트 만들기</button></div></div><div class="hero-summary"><span>개인 기준선 대비 보행 상태</span><strong id="home-score">—<small>/100</small></strong><p id="home-state">측정 기록을 기다리고 있어요.</p><span class="caption">질병 진단이 아닌 연구용 비교 점수</span></div></div><div class="stat-grid"><article class="panel stat"><span>오늘의 보행 기록</span><strong id="home-today">0<small>회</small></strong><p>오늘 저장한 Trial</p></article><article class="panel stat"><span>전체 누적 기록</span><strong id="home-total">0<small>회</small></strong><p>참여자별로 구분해 보관</p></article><article class="panel stat"><span>오늘의 복약 기록</span><strong id="home-med">0<small>/ 0회</small></strong><p>사용자가 입력한 복약 여부</p></article><article class="panel stat"><span>건강 리포트</span><strong id="home-reports">0<small>개</small></strong><p>저장된 기간별 리포트</p></article></div><div class="dashboard-grid"><article class="panel"><div class="panel-heading"><h2>최근 보행 기록</h2><button class="text-button" data-go="trends">전체 추이 →</button></div><div id="home-chart" class="trend-chart"></div><p class="caption">Trial별 저장 종합점수 · 서로 다른 조건·보정은 직접 비교에 주의하세요.</p></article><article class="panel"><div class="panel-heading"><h2>오늘의 관리</h2><button class="text-button" data-go="medications">복약 관리 →</button></div><div id="home-tasks"></div></article></div><div class="dashboard-grid"><article class="panel"><div class="panel-heading"><h2>기록에서 확인된 변화</h2><button class="text-button" data-go="analysis">분석 보기 →</button></div><div id="home-changes"></div></article><article class="panel"><div class="panel-heading"><h2>함께 확인할 준비</h2><button class="text-button" data-go="sharing">공유 자료 →</button></div><p class="body-copy">보호자·의료진에게 전달할 리포트와 질문을 한곳에 모아보세요.</p><div class="actions"><button class="secondary" data-go="chat">질문 기록하기</button><button class="secondary" data-go="care">방문 케어 요청서</button></div><p class="caption">메일·전화·의료기관 접수는 연결되어 있지 않습니다.</p></article></div></section>`;
const rest=`
<section data-view-panel="trends" hidden><div class="panel filter-bar"><label>시작일<input id="trend-start" type="date"></label><label>종료일<input id="trend-end" type="date"></label><label>보행 조건<select id="trend-condition"><option value="All">전체 조건</option>${['Normal','ReducedStride','Shuffling','Asymmetry'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>비교 지표<select id="trend-metric"><option value="overall">보행 상태 종합점수</option>${Object.entries(metricNames).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><button id="trend-apply">조회</button><button id="trend-export" class="secondary">추이 CSV</button></div><div class="panel spaced"><div class="panel-heading"><h2 id="trend-title">보행 상태 종합점수</h2><span id="trend-count" class="caption"></span></div><div id="trend-chart" class="trend-chart large"></div><p class="caption">일별·Trial별 기록을 실제 저장 시점으로 표시합니다. 빈 날짜와 미측정 값은 채우지 않습니다.</p></div><div class="panel spaced table-wrap"><table><thead><tr><th>측정 시각</th><th>조건 / Trial</th><th>종합점수</th><th>왼발 지표</th><th>오른발 지표</th><th>기록</th></tr></thead><tbody id="trend-table"></tbody></table></div></section>
<section data-view-panel="reports" hidden><div class="two-columns"><article class="panel"><p class="eyebrow">HEALTH REPORT</p><h2>나의 기록을 리포트로</h2><p class="body-copy">기간 안에 저장된 실제 보행 기록과 복약 체크를 요약합니다. 기록이 없으면 수치를 만들지 않습니다.</p><form id="report-form" class="form-grid"><label>시작일<input id="report-start" name="start" type="date" required></label><label>종료일<input id="report-end" name="end" type="date" required></label><label class="full">조건<select name="condition"><option value="All">전체 조건</option>${['Normal','ReducedStride','Shuffling','Asymmetry'].map(x=>`<option>${x}</option>`).join('')}</select></label><button type="submit" class="full">건강 리포트 생성</button></form></article><article class="panel"><p class="eyebrow">MONTHLY ROUTINE</p><h2>월간 자동 리포트</h2><p class="body-copy">지난달까지의 저장 기록이 있으면 월별 리포트를 자동 생성합니다. PC 서버가 켜진 동안 매시간 확인하며, 화면을 열 때도 확인합니다.</p><form id="settings-form" class="form-grid"><label class="check full"><input id="auto-monthly" type="checkbox"> 완료된 월의 리포트 자동 생성</label><label class="full">변화 확인 기준 (0~100)<input id="change-threshold" type="number" min="0" max="100" required></label><p class="caption full">개인 기준선 유사도 점수가 이 값 미만인 기록을 표시합니다. 임상적 위험도 기준이 아닙니다.</p><button type="submit" class="secondary full">설정 저장</button></form></article></div><div class="section-heading"><h2>저장된 리포트</h2><span>열람 · 파일 저장 · 인쇄/PDF</span></div><div id="report-list" class="record-list"></div></section>
<section data-view-panel="medications" hidden><div class="two-columns"><article class="panel"><h2>복약 일정 등록</h2><p class="body-copy">처방전이나 의료진이 안내한 내용을 그대로 입력하세요. 앱은 용량이나 약을 추천하지 않습니다.</p><form id="medication-form" class="form-grid"><label class="full">약 이름<input name="name" maxlength="80" required placeholder="처방받은 약 이름"></label><label class="full">처방 메모<input name="dose_note" maxlength="200" placeholder="처방전에 적힌 복용 방법"></label><label class="full">복약 시각<input name="times" required placeholder="예: 08:00, 13:00, 19:00"></label><label>시작일<input id="med-start" name="start_date" type="date" required></label><label>종료일 (선택)<input name="end_date" type="date"></label><button type="submit" class="full">복약 일정 등록</button></form></article><article class="panel"><div class="panel-heading"><h2>복약 체크</h2><input id="med-date" type="date" aria-label="복약 기록 날짜"></div><p class="caption">기록은 직접 입력한 상태이며 실제 복용을 확인하는 센서가 아닙니다.</p><div id="medication-due"></div></article></div><div class="section-heading"><h2>등록한 복약 일정</h2><span>등록 종료 후에도 이전 체크 기록은 보존됩니다.</span></div><div id="medication-list" class="record-list"></div><p class="note">복용 방법의 변경이나 누락분 처리 방법은 의료진·약사에게 확인하세요. <a href="https://www.nia.nih.gov/health/medicines-and-medication-management/taking-medicines-safely-you-age" target="_blank" rel="noopener">NIA 복약 안내</a></p></section>
<section data-view-panel="chat" hidden><div class="chat-layout"><article class="panel chat-panel"><div class="panel-heading"><div><h2>무엇이 궁금하신가요?</h2><p class="caption">기본 안내 모드 · 보행 AI 분석은 별도 버튼</p></div><span class="badge">이 PC에 질문 저장</span></div><div class="prompt-chips"><button class="secondary" data-question="센서 캘리브레이션은 어떻게 하나요?">센서 보정 방법</button><button class="secondary" data-question="내 보행 기록을 요약해 주세요.">내 기록 요약</button><button class="secondary" data-question="복약 관리에서 무엇을 기록하나요?">복약 기록 안내</button><button class="secondary" data-question="점수로 파킨슨병을 진단하나요?">점수의 의미</button></div><div id="question-log" class="question-log" role="log" aria-live="polite"></div><form id="question-form" class="question-form"><label for="question-input" class="sr-only">질문 입력</label><textarea id="question-input" name="question" rows="2" maxlength="1000" required placeholder="측정·기록에 관해 궁금한 점을 입력하세요."></textarea><button type="submit">질문 남기기</button></form></article><aside class="panel chat-note"><p class="eyebrow">CARE NOTES</p><h2>상담을 위한 준비</h2><p class="body-copy">기록에서 궁금했던 변화, 증상이 느껴진 시점, 복약 관련 질문을 남겨두세요.</p><p class="caption">질문 남기기는 정해진 기본 안내와 기록 요약을 제공합니다. 실제 보행 데이터의 AI 설명은 위의 보행 기록 AI 분석 열기 버튼에서 실행하세요.</p><button id="questions-export" class="secondary">질문 기록 내려받기</button><button data-go="sharing" class="secondary">리포트 공유 준비</button></aside></div></section>
<section data-view-panel="sharing" hidden><div class="two-columns"><article class="panel"><h2>함께 확인할 사람</h2><p class="body-copy">직접 등록한 대상에게 전달할 자료를 준비합니다.</p><form id="contact-form" class="form-grid"><label class="full">이름 또는 구분<input name="name" maxlength="80" required placeholder="직접 입력"></label><label class="full">관계<select name="role"><option value="guardian">보호자</option><option value="clinician">의료진</option></select></label><label class="full">연락처 메모 (선택)<input name="contact_note" maxlength="200" placeholder="이 PC에만 저장됩니다."></label><button type="submit" class="full">대상 등록</button></form><div id="contact-list" class="compact-list"></div></article><article class="panel"><h2>공유 자료 준비</h2><form id="share-form" class="form-grid"><label class="full">리포트<select id="share-report" name="report_id" required></select></label><label class="full">공유 대상<select id="share-contact" name="contact_id" required></select></label><label class="full">전달 메모<textarea name="note" rows="3" maxlength="500" placeholder="함께 확인할 내용"></textarea></label><label class="check full"><input name="consent" type="checkbox" required> 이 리포트의 보행·복약 기록을 확인했으며 공유 파일 생성을 선택합니다.</label><button type="submit" class="full">공유 자료 만들기</button></form><p class="caption">이 버튼은 공유 파일을 준비합니다. 메일·문자·전화 전송이나 원격 열람 권한은 생성하지 않습니다.</p></article></div><div class="section-heading"><h2>준비한 공유 자료</h2><span>외부 미전송</span></div><div id="share-list" class="record-list"></div></section>
<section data-view-panel="care" hidden><div class="two-columns"><article class="panel"><p class="eyebrow">VISIT CARE</p><h2>방문 케어 상담 요청서</h2><p class="body-copy">필요한 도움과 희망 일정을 정리하세요. 요청서를 내려받아 선택한 기관에 직접 전달할 수 있습니다.</p><form id="care-form" class="form-grid"><label class="full">필요한 도움<select name="service"><option>보행 기록 상담</option><option>일상 돌봄 상담</option><option>방문 케어 상담</option></select></label><label>희망일<input id="care-date" name="preferred_date" type="date" required></label><label>지역<input name="region" maxlength="120" required placeholder="예: 서울 도봉구"></label><label class="full">문의할 기관 (선택)<input name="requested_to" maxlength="120" placeholder="직접 입력 · 제휴 기관 자동 연결 없음"></label><label class="full">요청 내용<textarea name="note" rows="4" maxlength="1000" required placeholder="현재 필요한 도움과 문의할 내용을 적으세요."></textarea></label><button type="submit" class="full">요청서 저장</button></form></article><article class="panel"><h2>요청 전 확인하기</h2><ol class="care-steps"><li>보행 기록과 질문을 정리해요.</li><li>희망 지역과 필요한 도움을 적어요.</li><li>요청서를 저장하고 내려받아요.</li><li>선택한 기관에 직접 문의해요.</li></ol><p class="research-note">현재는 요청서 작성·보관 기능입니다. 기관 접수·예약 확정·결제·방문 배정은 연결되어 있지 않습니다.</p><button class="secondary" data-go="reports">건강 리포트 확인</button></article></div><div class="section-heading"><h2>작성한 요청서</h2><span>PC 로컬 보관 · 기관 미접수</span></div><div id="care-list" class="record-list"></div></section>`;

$('sidebar').innerHTML=sidebar;$('platform-before').innerHTML='<div id="platform-notice" class="notice" role="status" aria-live="polite" hidden></div>'+intro+home;$('platform-after').innerHTML=rest;
const analysisSwitcher=node('div',undefined,'analysis-switcher');analysisSwitcher.innerHTML='<span class="caption">비교할 발</span><div class="tabs" role="group" aria-label="분석할 발"><button id="analysis-select-L" class="tab" aria-pressed="true">왼발</button><button id="analysis-select-R" class="tab" aria-pressed="false">오른발</button></div>';
const scoreTime=node('span','저장된 점수 없음','caption');scoreTime.id='home-score-time';$('home-state').after(scoreTime);
document.querySelector('[data-view-panel="analysis"]').prepend(analysisSwitcher);
for(const side of ['L','R'])$('analysis-select-'+side).addEventListener('click',()=>$('select-'+side).click());
const intakeHistory=node('div',undefined,'panel spaced');intakeHistory.innerHTML='<h2>선택 날짜의 복약 체크 기록</h2><div id="intake-history"></div>';
document.querySelector('[data-view-panel="medications"]').append(intakeHistory);
document.querySelector('.research-note').classList.add('global-research-note');
const mobileMenu=matchMedia('(max-width:760px)');
function syncMenu(){const open=document.body.classList.contains('menu-open');$('sidebar').inert=mobileMenu.matches&&!open;$('sidebar').setAttribute('aria-hidden',String(mobileMenu.matches&&!open));}
mobileMenu.addEventListener('change',syncMenu);
$('menu-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');$('menu-toggle').setAttribute('aria-expanded',String(open));syncMenu();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('menu-open')){document.body.classList.remove('menu-open');$('menu-toggle').setAttribute('aria-expanded','false');syncMenu();$('menu-toggle').focus();}});
document.addEventListener('click',event=>{const section=event.target.closest('[data-intro-scroll]');if(section)document.getElementById(section.dataset.introScroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});const go=event.target.closest('[data-go],[data-nav]');if(go)navigate(go.dataset.go||go.dataset.nav);const chip=event.target.closest('[data-question]');if(chip){$('question-input').value=chip.dataset.question;$('question-input').focus();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
window.addEventListener('earlybird:participant-changing',event=>{participant=event.detail.participant;data=null;requestVersion++;$('platform-dialog').close();for(const id of ['medication-form','contact-form','share-form','care-form','question-form'])$(id).reset();$('med-start').value=dayNow();$('care-date').value=dayNow();$('med-date').value=dayNow();renderLoading();});
window.addEventListener('earlybird:state',event=>{participant=event.detail.participant;coreState=event.detail.state;data=null;message('');$('platform-dialog').close();renderLoading();void load();});
function renderLoading(){for(const id of ['home-score','home-today','home-total','home-med','home-reports'])$(id).textContent='—';$('home-state').textContent='기록을 불러오는 중입니다.';$('home-score-time').textContent='';for(const id of ['intake-history','home-chart','home-tasks','home-changes','report-list','trend-table','trend-chart','medication-list','medication-due','question-log','contact-list','share-list','care-list'])$(id).replaceChildren(node('p','기록을 불러오는 중입니다.','empty'));for(const id of ['share-report','share-contact'])$(id).replaceChildren();}
function empty(target,text){target.replaceChildren(node('div',text,'empty'));}
function button(label,handler,secondary=true){const b=node('button',label,secondary?'secondary':'');b.type='button';b.addEventListener('click',async()=>{b.disabled=true;try{await handler();}catch(e){message(e.message,true);}finally{b.disabled=false;}});return b;}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=node('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function jsonDownload(item){download(`ENDEAVOR_${participant}_${item.kind}_${item.id}.json`,JSON.stringify(item,null,2));}
function scalar(value){return Number.isFinite(value)?value:null;}
function trendRows(){if(!data)return[];const start=$('trend-start').value,end=$('trend-end').value,condition=$('trend-condition').value;return data.trend.filter(t=>(!start||dateOf(t.created_at)>=start)&&(!end||dateOf(t.created_at)<=end)&&(condition==='All'||t.condition===condition));}
function chart(target,rows,key){target.replaceChildren();const series=key==='overall'?[{side:null,color:'#327f79',name:'종합점수'}]:[{side:'L',color:'#327f79',name:'왼발'},{side:'R',color:'#3d4550',name:'오른발'}];const get=(t,side)=>scalar(side?(t.sides[side]?.ready?t.sides[side].metrics[key]:null):t.overall);const vals=rows.flatMap(t=>series.map(s=>get(t,s.side))).filter(Number.isFinite);if(!vals.length){empty(target,'아직 표시할 기록이 없습니다. 실시간 측정에서 보행을 기록해 주세요.');return;}const times=rows.map(t=>new Date(t.created_at).getTime()),minT=Math.min(...times),maxT=Math.max(...times);let lo=key==='overall'?0:Math.min(0,...vals),hi=key==='overall'?100:Math.max(...vals)*1.1;if(hi<=lo)hi=lo+1;const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 800 230');svg.setAttribute('role','img');svg.setAttribute('aria-label',key==='overall'?'저장된 Trial 종합점수 추이':metricNames[key]+' 좌우 추이');const add=(name,attrs,text)=>{const n=document.createElementNS(ns,name);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;svg.append(n);return n;};for(let i=0;i<5;i++){const y=20+i*42;add('line',{x1:42,x2:775,y1:y,y2:y,stroke:'#e7ecee'});add('text',{x:32,y:y+4,'text-anchor':'end',fill:'#626972','font-size':11},number(hi-(hi-lo)*i/4,1));}series.forEach(s=>{let path='',prior=false;rows.forEach((t,i)=>{const value=get(t,s.side);if(value===null){prior=false;return;}const x=maxT===minT?400:55+(times[i]-minT)/(maxT-minT)*710,y=188-(value-lo)/(hi-lo)*168;path+=(prior?'L':'M')+x.toFixed(1)+','+y.toFixed(1)+' ';prior=true;const dot=add('circle',{cx:x,cy:y,r:4,fill:s.color});const title=document.createElementNS(ns,'title');title.textContent=`${stamp(t.created_at)} · ${s.name}: ${number(value,2)} · ${t.condition}`;dot.append(title);});add('path',{d:path,fill:'none',stroke:s.color,'stroke-width':2,...(s.side==='R'?{'stroke-dasharray':'6 3'}:{})});});add('text',{x:55,y:218,fill:'#626972','font-size':11},dateOf(rows[0].created_at));add('text',{x:765,y:218,'text-anchor':'end',fill:'#626972','font-size':11},dateOf(rows.at(-1).created_at));target.append(svg);if(key!=='overall')target.append(node('p','실선: 왼발 · 점선: 오른발','caption'));}
function due(dateValue=dayNow()){return data.medications.filter(m=>m.active&&m.start_date<=dateValue&&(!m.end_date||m.end_date>=dateValue)).flatMap(m=>m.times.map(time=>({med:m,time,record:data.intakes.find(x=>x.medication_id===m.id&&x.date===dateValue&&x.time===time)}))).sort((a,b)=>a.time.localeCompare(b.time));}
function setOptions(id,items,placeholder){const select=$(id),previous=select.value;select.replaceChildren();const none=node('option',placeholder);none.value='';select.append(none);for(const item of items){const op=node('option',item.label);op.value=item.id;select.append(op);}if(items.some(x=>x.id===previous))select.value=previous;}
function recordCard(title,subtitle){const box=node('article',undefined,'panel record-card'),body=node('div'),actions=node('div',undefined,'actions');body.append(node('h3',title),node('p',subtitle,'caption'));box.append(body,actions);return{box,body,actions};}
function render(){if(!data)return;const today=dayNow(),items=due(),latest=[...data.trend].reverse().find(t=>Number.isFinite(t.overall));$('home-score').innerHTML=esc(number(latest?.overall,0))+'<small>/100</small>';$('home-score-time').textContent=latest?'최근 저장: '+stamp(latest.created_at):'저장된 점수 없음';$('home-state').textContent=latest?(latest.overall<data.settings.change_score_threshold?'개인 기준선 대비 변화 확인 필요':'개인 기준선과 비교할 수 있어요.'):'보정과 Normal 기준선 수집이 필요해요.';$('home-today').innerHTML=data.trend.filter(t=>dateOf(t.created_at)===today).length+'<small>회</small>';$('home-total').innerHTML=data.trend.length+'<small>회</small>';$('home-med').innerHTML=items.filter(x=>x.record?.status==='taken').length+`<small>/ ${items.length}회</small>`;$('home-reports').innerHTML=data.reports.length+'<small>개</small>';chart($('home-chart'),data.trend.slice(-14),'overall');
 $('home-tasks').replaceChildren();if(!items.length)empty($('home-tasks'),'등록한 오늘의 복약 일정이 없습니다.');for(const item of items.slice(0,4)){const row=node('div',undefined,'task-row');row.append(node('strong',item.time),node('span',item.med.name),node('span',item.record?.status==='taken'?'복용 기록':item.record?.status==='skipped'?'건너뜀 기록':'미기록','badge'));$('home-tasks').append(row);}
 const changes=data.trend.filter(t=>Number.isFinite(t.overall)&&t.overall<data.settings.change_score_threshold).slice(-3).reverse();$('home-changes').replaceChildren();if(!changes.length)empty($('home-changes'),data.trend.length?'설정 기준 미만의 유효 점수가 없습니다. 이것이 질병이 없다는 뜻은 아닙니다.':'저장된 보행 기록이 없습니다.');for(const t of changes){const row=node('div',undefined,'task-row');row.append(node('span',`${dateOf(t.created_at)} · ${t.condition}`),node('strong',number(t.overall,0)+'/100'),node('span','변화 확인','badge'));$('home-changes').append(row);}
 $('auto-monthly').checked=data.settings.auto_monthly;$('change-threshold').value=data.settings.change_score_threshold;renderTrend();renderReports();renderMedications();renderIntakeHistory();renderQuestions();renderContacts();renderShares();renderCare();}
function renderTrend(){if(!data)return;const rows=trendRows(),key=$('trend-metric').value;$('trend-title').textContent=key==='overall'?'보행 상태 종합점수':metricNames[key]+' ('+metricUnit(key)+')';$('trend-count').textContent=rows.length+'개 Trial';chart($('trend-chart'),rows,key);$('trend-table').replaceChildren();for(const t of [...rows].reverse()){const row=node('tr');for(const value of [stamp(t.created_at),`${t.condition} / ${t.trial}`,number(t.overall,0),key==='overall'?'—':number(t.sides.L?.ready?t.sides.L.metrics[key]:null,2),key==='overall'?'—':number(t.sides.R?.ready?t.sides.R.metrics[key]:null,2)])row.append(node('td',value));const td=node('td'),a=node('a','원시 CSV');a.href=`/api/trials/${t.id}/raw.csv`;a.download='';td.append(a);row.append(td);$('trend-table').append(row);}if(!rows.length){const row=node('tr'),td=node('td','조건에 맞는 기록이 없습니다.');td.colSpan=6;row.append(td);$('trend-table').append(row);}}
function reportHTML(report){return `<div class="report-document"><p class="eyebrow">ENDEAVOR / HEALTH REPORT</p><h2>${esc(report.title)}</h2><p>참여자 ${esc(report.participant_id)} · ${esc(report.start)} ~ ${esc(report.end)} · ${esc(report.condition)}</p><div class="report-stats"><div><span>저장 보행</span><strong>${report.trial_count}회</strong></div><div><span>평균 유사도 점수</span><strong>${number(report.average_score,1)} /100</strong></div><div><span>변화 확인 기록</span><strong>${report.change_count}회</strong></div></div><p class="caption">점수 유효 ${report.scored_trials}회 / 전체 ${report.trial_count}회 · 보정 기준 ${report.calibration_count}개 · 변화 기준 ${number(report.change_score_threshold,0)}점 미만</p><h3>좌우 보행 지표 평균</h3><table><thead><tr><th>지표</th><th>왼발</th><th>오른발</th></tr></thead><tbody>${Object.entries(metricNames).map(([key,label])=>`<tr><td>${label} (${metricUnit(key)})</td><td>${number(report.sides.L.metrics[key],2)}</td><td>${number(report.sides.R.metrics[key],2)}</td></tr>`).join('')}</tbody></table><h3>복약 체크 기록</h3><p>복용 기록 ${report.medication.taken_records}회 · 건너뜀 기록 ${report.medication.skipped_records}회</p><p class="caption">${esc(report.medication.note)}</p><h3>해석 범위</h3><ul>${report.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="caption">생성 시각 ${stamp(report.created_at)} · 이 문서는 의료진의 진단서가 아닙니다.</p></div>`;}
function printHTML(title,html){printing={title,html};$('print-area').innerHTML=html;window.print();}
function exportHTML(title,html){const style='body{font-family:Arial,"Malgun Gothic",sans-serif;max-width:850px;margin:40px auto;padding:20px;color:#2d2d2d;line-height:1.7}h2{border-bottom:3px solid #6fc5c1;padding-bottom:14px}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}.report-stats{display:flex;justify-content:space-between;gap:24px;margin:24px 0}.report-stats span,.report-stats strong{display:block}.caption{font-size:12px;color:#626972}.research-document svg{width:100%;height:auto;max-height:300px}.research-chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{padding:16px;margin-top:16px;border:1px solid #ddd}.ai-text{white-space:pre-wrap}@media(max-width:650px){.research-chart-grid{display:block}}@media print{.panel{break-inside:avoid}.research-chart-grid{display:block}}';download(`ENDEAVOR_${participant}_${title}.html`,`<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(title)}</title><style>${style}</style><body>${html}</body></html>`,'text/html;charset=utf-8');}
function modal(title,html,actions=[]){$('platform-dialog-title').textContent=title;$('platform-dialog-content').innerHTML=html;$('platform-dialog-actions').replaceChildren(...actions);$('platform-dialog').showModal();}
function showReport(report){const html=reportHTML(report);modal('건강 리포트',html,[button('인쇄·PDF 저장',()=>printHTML(report.title,html),false),button('HTML 파일 저장',()=>exportHTML('report_'+report.id,html)),button('JSON 저장',()=>jsonDownload(report))]);}
function renderReports(){const target=$('report-list');target.replaceChildren();if(!data.reports.length)empty(target,'아직 리포트가 없습니다. 기간을 지정해 생성하거나 완료된 월의 기록을 모아보세요.');for(const report of data.reports){const c=recordCard(report.title,`${report.start} ~ ${report.end} · ${report.trial_count}회 · ${report.automatic?'월간 자동 생성':'직접 생성'}`);c.actions.append(button('리포트 열기',()=>showReport(report),false),button('공유 준비',()=>{$('share-report').value=report.id;navigate('sharing');}));target.append(c.box);}setOptions('share-report',data.reports.map(x=>({id:x.id,label:x.title})),'리포트를 선택하세요');}
function renderMedications(){const target=$('medication-list');target.replaceChildren();if(!data.medications.length)empty(target,'등록한 복약 일정이 없습니다.');for(const med of data.medications){const c=recordCard(med.name,`${med.times.join(' · ')} · ${med.start_date} ~ ${med.end_date||'종료일 미정'} · ${med.active?'사용 중':'등록 종료'}`);c.body.append(node('p',med.dose_note,'caption'));if(med.active)c.actions.append(button('일정 등록 종료',async()=>{await action('archive-medication',{id:med.id});message('일정 등록을 종료했습니다. 실제 복용 중단 지시가 아니며 과거 기록은 유지됩니다.');}));target.append(c.box);}const date=$('med-date').value||dayNow(),targetDue=$('medication-due');targetDue.replaceChildren();const items=due(date);if(!items.length)empty(targetDue,'이 날짜의 사용 중인 일정이 없습니다.');for(const item of items){const box=node('div',undefined,'dose-row');box.append(node('strong',`${item.time} · ${item.med.name}`),node('p',item.med.dose_note,'caption'));const group=node('div',undefined,'actions');for(const[state,label]of [['taken','복용 기록'],['skipped','건너뜀'],['pending','체크 취소']]){const b=button(label,async()=>{await action('intakes',{medication_id:item.med.id,date,time:item.time,status:state});message('복약 체크를 저장했습니다.');},item.record?.status!==state);b.disabled=date>dayNow();group.append(b);}box.append(node('span',item.record?.status==='taken'?'복용으로 기록됨':item.record?.status==='skipped'?'건너뜀으로 기록됨':'미기록','caption'),group);targetDue.append(box);}}
function renderIntakeHistory(){const target=$('intake-history'),date=$('med-date').value||dayNow();target.replaceChildren();const logs=data.intakes.filter(x=>x.date===date);if(!logs.length)empty(target,'이 날짜에 남긴 복약 체크가 없습니다.');for(const item of logs){const row=node('div',undefined,'task-row');row.append(node('strong',item.time),node('span',item.name),node('span',item.status==='taken'?'복용 기록':item.status==='skipped'?'건너뜀 기록':'체크 취소','badge'));target.append(row);}}
function renderQuestions(){const target=$('question-log');target.replaceChildren();if(!data.questions.length)empty(target,'질문을 남기면 기본 안내 답변과 함께 이곳에 보관됩니다.');for(const q of [...data.questions].reverse()){const user=node('div',undefined,'chat-user');user.append(node('span','나의 질문','chat-label'),node('p',q.question));const reply=node('div',undefined,'chat-reply');reply.append(node('span',q.label,'chat-label'),node('p',q.answer));const sources=node('div',undefined,'sources');for(const source of q.sources){const a=node('a',source.title);a.href=source.url;a.target='_blank';a.rel='noopener';sources.append(a);}reply.append(sources);target.append(user,reply);}target.scrollTop=target.scrollHeight;}
function renderContacts(){const target=$('contact-list');target.replaceChildren();const contacts=data.contacts.filter(x=>x.active);if(!contacts.length)empty(target,'등록한 공유 대상이 없습니다.');for(const contact of contacts){const row=node('div',undefined,'contact-row');const body=node('div');body.append(node('strong',contact.name),node('p',(contact.role==='guardian'?'보호자':'의료진')+(contact.contact_note?' · '+contact.contact_note:''),'caption'));row.append(body,button('등록 해제',async()=>{await action('archive-contact',{id:contact.id});message('대상 등록을 해제했습니다.');}));target.append(row);}setOptions('share-contact',contacts.map(x=>({id:x.id,label:(x.role==='guardian'?'보호자 · ':'의료진 · ')+x.name})),'공유 대상을 선택하세요');}
function renderShares(){const target=$('share-list');target.replaceChildren();if(!data.shares.length)empty(target,'준비한 공유 자료가 없습니다. 리포트와 대상을 선택하세요.');for(const item of data.shares){const html=`<p>공유 대상: ${esc(item.recipient.name)} (${item.recipient.role==='guardian'?'보호자':'의료진'})</p><p>전달 메모: ${esc(item.note||'없음')}</p><p class="caption">파일 준비됨 · 외부 미전송</p>`+reportHTML(item.report_snapshot);const c=recordCard(item.report_snapshot.title,`${item.recipient.name} · ${stamp(item.created_at)} · 파일 준비됨 / 외부 미전송`);c.actions.append(button('자료 확인',()=>modal('공유 자료 미리보기',html,[button('HTML 내려받기',()=>exportHTML('share_'+item.id,html),false),button('인쇄·PDF 저장',()=>printHTML('공유 자료',html))]),false),button('공유 파일 내려받기',()=>exportHTML('share_'+item.id,html)));target.append(c.box);}}
function careHTML(item){return `<div class="report-document"><p class="eyebrow">ENDEAVOR / VISIT CARE REQUEST</p><h2>방문 케어 상담 요청서</h2><p>참여자 코드: ${esc(item.participant_id)}</p><table>${[['필요한 도움',item.service],['희망일',item.preferred_date],['지역',item.region],['문의할 기관',item.requested_to||'미지정'],['요청 내용',item.note],['상태',item.status==='cancelled'?'로컬 작성 취소':'로컬 작성 완료 · 기관 미접수']].map(([k,v])=>`<tr><th>${k}</th><td>${esc(v)}</td></tr>`).join('')}</table><p>이 요청서는 기관에 전송되지 않았으며 예약이나 서비스 배정이 아닙니다.</p></div>`;}
function renderCare(){const target=$('care-list');target.replaceChildren();if(!data.cares.length)empty(target,'작성한 요청서가 없습니다.');for(const item of data.cares){const html=careHTML(item),c=recordCard(item.service,`${item.preferred_date} · ${item.region} · ${item.status==='cancelled'?'작성 취소':'작성 완료 / 기관 미접수'}`);c.actions.append(button('요청서 보기',()=>modal('방문 케어 요청서',html,[button('인쇄·PDF 저장',()=>printHTML('방문 케어 요청서',html),false),button('파일 내려받기',()=>exportHTML('care_'+item.id,html))]),false),button('요청서 내려받기',()=>exportHTML('care_'+item.id,html)));if(item.status!=='cancelled')c.actions.append(button('작성 취소',async()=>{await action('cancel-care',{id:item.id});message('로컬 요청서 작성을 취소했습니다.');}));target.append(c.box);}}

function form(id,name,convert,success){$(id).addEventListener('submit',async event=>{event.preventDefault();const f=event.currentTarget,submit=f.querySelector('[type=submit]');submit.disabled=true;try{const who=participant;const result=await action(name,convert(Object.fromEntries(new FormData(f)),f));if(participant!==who)return;if(id==='question-form')$('question-input').value='';else if(['contact-form','medication-form','care-form'].includes(id)){f.reset();if(id==='medication-form')$('med-start').value=dayNow();if(id==='care-form')$('care-date').value=dayNow();}message(success);if(name==='reports')showReport(result);if(name==='shares')f.reset();}catch(e){message(e.message,true);}finally{submit.disabled=false;}});}
form('report-form','reports',p=>p,'리포트를 생성해 PC에 저장했습니다.');
form('settings-form','settings',()=>({auto_monthly:$('auto-monthly').checked,change_score_threshold:Number($('change-threshold').value)}),'월간 리포트·변화 표시 설정을 저장했습니다.');
form('medication-form','medications',p=>({...p,times:p.times.split(',').map(x=>x.trim())}),'복약 일정을 등록했습니다.');
form('contact-form','contacts',p=>p,'공유 대상을 등록했습니다. 외부 메시지는 보내지 않았습니다.');
form('share-form','shares',(p,f)=>({...p,consent:f.elements.consent.checked}),'공유 파일을 준비했습니다. 외부 전송은 하지 않았습니다.');
form('care-form','care',p=>p,'방문 케어 요청서를 저장했습니다. 기관에 접수한 것은 아닙니다.');
form('question-form','questions',p=>p,'질문과 기본 안내 답변을 저장했습니다.');
$('med-date').addEventListener('change',()=>{if(data){renderMedications();renderIntakeHistory();}});
$('trend-apply').addEventListener('click',()=>{if($('trend-start').value&&$('trend-end').value&&$('trend-start').value>$('trend-end').value)return message('조회 시작일과 종료일을 확인하세요.',true);renderTrend();message('저장된 기록을 조회했습니다.');});
$('trend-export').addEventListener('click',()=>{const rows=trendRows();if(!rows.length)return message('내려받을 추이 기록이 없습니다.',true);const cell=value=>'"'+String(value??'').replaceAll('"','""')+'"',csv=[['participant_id','created_at','condition','trial','overall_score',...Object.keys(metricNames).flatMap(k=>['L_'+k,'R_'+k])],...rows.map(t=>[participant,t.created_at,t.condition,t.trial,t.overall,...Object.keys(metricNames).flatMap(k=>['L','R'].map(s=>t.sides[s]?.ready?t.sides[s].metrics[k]:null))])].map(row=>row.map(cell).join(',')).join('\r\n');download('ENDEAVOR_'+participant+'_trend.csv','\ufeff'+csv,'text/csv;charset=utf-8');});
$('questions-export').addEventListener('click',()=>{if(!data?.questions.length)return message('저장한 질문이 없습니다.',true);download('ENDEAVOR_'+participant+'_questions.txt',data.questions.map(q=>`${stamp(q.created_at)}\n질문: ${q.question}\n${q.label}: ${q.answer}\n출처: ${q.sources.map(s=>s.url).join(', ')}`).join('\n\n'),'text/plain;charset=utf-8');});
const today=dayNow(),monthStart=today.slice(0,8)+'01';for(const id of ['report-start','trend-start'])$(id).value=monthStart;for(const id of ['report-end','trend-end','med-start','med-date','care-date'])$(id).value=today;$('care-date').min=today;
const connectionObserver=new MutationObserver(()=>{const n=['L','R'].filter(s=>$('status-'+s)?.textContent==='실시간 수신').length;$('connection-mini').textContent=n?`${n}/2개 발 실시간 수신`:'센서 연결 대기';$('connection-mini').classList.toggle('live',n>0);});
for(const side of ['L','R'])connectionObserver.observe($('status-'+side),{subtree:true,characterData:true,childList:true});
let lastDay=today;setInterval(()=>{const next=dayNow();if(next!==lastDay){lastDay=next;void load();}},60000);
navigate(location.hash.slice(1));void load();

window.earlybirdReportTools={modal,printHTML,exportHTML,download};
